class Produto {
  nome: string;
  preco: number;

  constructor(nome: string, preco: number) {
    this.nome = nome;
    this.preco = preco;
  }
}

const caneca = new Produto("Caneca", 8.5);
console.log(caneca.nome); // Caneca
console.log(caneca.preco); // 8.5

// Um parâmetro do construtor com o tipo errado é recusado, como em qualquer função tipada.
// @ts-expect-error preco tem de ser number, não uma string
new Produto("Copo", "8.5");

class ContaBancaria {
  public titular: string; // visível em qualquer lado; é o valor por omissão sem modificador
  private saldo: number; // só dentro desta classe
  protected numeroConta: string; // dentro desta classe e das subclasses

  constructor(titular: string, saldo: number, numeroConta: string) {
    this.titular = titular;
    this.saldo = saldo;
    this.numeroConta = numeroConta;
  }

  resumo(): string {
    // dentro da própria classe, os três modificadores são visíveis.
    return `${this.titular}: ${this.saldo} (conta ${this.numeroConta})`;
  }
}

const conta = new ContaBancaria("Ana", 500, "PT001");
console.log(conta.titular); // Ana
console.log(conta.resumo()); // Ana: 500 (conta PT001)

// @ts-expect-error saldo é private: só é visível dentro da própria classe
conta.saldo;

// @ts-expect-error numeroConta é protected: visível na classe e em subclasses, não fora
conta.numeroConta;

class ContaPrivate {
  private saldo: number;

  constructor(saldo: number) {
    this.saldo = saldo;
  }
}

const conta = new ContaPrivate(100);

// @ts-expect-error saldo é private: o compilador recusa o acesso direto a partir de fora
console.log(conta.saldo);

// Um cast para any tira o compilador da jogada, e o acesso funciona em runtime.
console.log((conta as any).saldo); // 100

// A prova está no JavaScript emitido: "private" desaparece, fica só a propriedade normal.
// class ContaPrivate {
//     saldo;
//     constructor(saldo) { this.saldo = saldo; }
// }

class ContaHash {
  #saldo: number;

  constructor(saldo: number) {
    this.#saldo = saldo;
  }
}

// Uma classe sem relação nenhuma com ContaHash, mas que também declara um campo #saldo.
// É preciso declará-lo aqui para poder sequer escrever a sintaxe alvo.#saldo: um campo
// com # só existe dentro do âmbito léxico da classe que o declara.
class Intruso {
  #saldo = 0;

  ler(alvo: object): number {
    // @ts-expect-error alvo não é tipado como uma classe que tenha este #saldo
    return alvo.#saldo;
  }
}

const conta = new ContaHash(100);
const intruso = new Intruso();

try {
  console.log(intruso.ler(conta));
} catch (erro) {
  // O JavaScript real bloqueia o acesso: #saldo de ContaHash e #saldo de Intruso são
  // campos distintos, mesmo com o mesmo nome.
  console.log("erro em runtime:", (erro as Error).message);
  // erro em runtime: Cannot read private member #saldo from an object whose class did not declare it
}

class Veiculo {
  protected matricula: string;

  constructor(matricula: string) {
    this.matricula = matricula;
  }
}

class Carro extends Veiculo {
  descricao(): string {
    // protected é visível na própria classe e em qualquer subclasse.
    return `Carro com matrícula ${this.matricula}`;
  }
}

const carro = new Carro("00-AA-00");
console.log(carro.descricao()); // Carro com matrícula 00-AA-00

// @ts-expect-error matricula é protected: não é visível fora da hierarquia de classes
console.log(carro.matricula);

class Utilizador {
  readonly id: number;
  nome: string;

  constructor(id: number, nome: string) {
    this.id = id; // atribuir a um campo readonly dentro do construtor é permitido
    this.nome = nome;
  }

  mudarId(novoId: number): void {
    // @ts-expect-error id é readonly: só pode ser atribuído no construtor, nem em outro método
    this.id = novoId;
  }
}

const u = new Utilizador(1, "Rui");
console.log(u.id); // 1

// @ts-expect-error readonly também bloqueia a atribuição a partir de fora da classe
u.id = 2;
console.log(u.id); // 2 — a marca readonly é só verificação de compilação, como no Módulo 02

