class Funcionario {
  nome: string;
  private salario: number;

  constructor(nome: string, salario: number) {
    this.nome = nome;
    this.salario = salario;
  }

  aumentar(percentagem: number): void {
    this.salario = this.salario * (1 + percentagem / 100);
  }

  salarioAtual(): number {
    return this.salario;
  }
}

const rui = new Funcionario("Rui", 1000);
rui.aumentar(10);
console.log(rui.salarioAtual()); // 1100
console.log(rui.nome); // Rui

// @ts-expect-error salario é private: não é visível fora da classe Funcionario
console.log(rui.salario);

class CofrePrivate {
  private codigo: string;
  constructor(codigo: string) {
    this.codigo = codigo;
  }
}

class CofreHash {
  #codigo: string;
  constructor(codigo: string) {
    this.#codigo = codigo;
  }
}

const c1 = new CofrePrivate("1234");
const c2 = new CofreHash("1234");

// O cast para any funciona: private é só verificação de compilação.
console.log((c1 as any).codigo); // 1234

// Uma classe intrusa com um #codigo homónimo consegue escrever a expressão, mas o
// runtime bloqueia porque #codigo de CofreHash e #codigo desta classe são campos distintos.
class Espiao {
  #codigo = "";
  tentar(alvo: object): string {
    // @ts-expect-error alvo (object) não tem o #codigo declarado nesta classe
    return alvo.#codigo;
  }
}

const espiao = new Espiao();
try {
  console.log(espiao.tentar(c2));
} catch (erro) {
  console.log("bloqueado:", (erro as Error).message);
}

class Animal {
  protected nome: string;

  constructor(nome: string) {
    this.nome = nome;
  }
}

class Cao extends Animal {
  latir(): string {
    return `${this.nome} diz Au!`;
  }
}

class Gato extends Animal {
  miar(): string {
    return `${this.nome} diz Miau!`;
  }
}

const bobi = new Cao("Bobi");
console.log(bobi.latir()); // Bobi diz Au!

const mimi = new Gato("Mimi");
console.log(mimi.miar()); // Mimi diz Miau!

// @ts-expect-error nome é protected: acessível na classe e nas subclasses, não fora delas
console.log(bobi.nome);

class RegistoAuditoria {
  readonly id: number;
  protected instanteUnix: number;
  private detalhes: string;

  constructor(id: number, instanteUnix: number, detalhes: string) {
    this.id = id;
    this.instanteUnix = instanteUnix;
    this.detalhes = detalhes;
  }

  resumo(): string {
    return `#${this.id} às ${this.instanteUnix}: ${this.detalhes}`;
  }
}

class RegistoErro extends RegistoAuditoria {
  descricaoComHora(): string {
    // instanteUnix é protected: a subclasse acede-lhe diretamente.
    return `erro registado no instante ${this.instanteUnix}`;
  }
}

const registo = new RegistoErro(1, 1700000000, "ligação recusada");
console.log(registo.resumo()); // #1 às 1700000000: ligação recusada
console.log(registo.descricaoComHora()); // erro registado no instante 1700000000

// @ts-expect-error id é readonly: não pode ser reatribuído fora do construtor
registo.id = 99;
console.log(registo.id); // 99 — readonly é só verificação de compilação, o valor muda na mesma

// @ts-expect-error instanteUnix é protected: não é visível fora da hierarquia de classes
console.log(registo.instanteUnix);

// @ts-expect-error detalhes é private: não é visível fora de RegistoAuditoria
console.log(registo.detalhes);

// O cast para any confirma que os três bloqueios são só do compilador: todos cedem.
console.log((registo as any).detalhes); // ligação recusada
